package com.bank.maint.service;

import com.bank.maint.model.Interval;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.logging.Logger;

// Collapses overlapping lock windows into minimal distinct locked periods.
public class LockWindowMerger {
    private static final Logger log = Logger.getLogger(LockWindowMerger.class.getName());

    public List<Interval> mergeLockedPeriods(List<Interval> windows) {
        List<Interval> merged = new ArrayList<>();
        if (windows == null || windows.isEmpty()) {
            return merged;
        }
        List<Interval> sorted = new ArrayList<>(windows);
        sorted.sort(Comparator.comparingInt(Interval::getStart));

        int curStart = sorted.get(0).getStart();
        int curEnd = sorted.get(0).getEnd();

        for (int i = 1; i < sorted.size(); i++) {
            Interval next = sorted.get(i);
            if (next.getStart() <= curEnd) {
                // Overlap or touch: extend; take max end for contained intervals.
                int newEnd = Math.max(curEnd, next.getEnd());
                final int cs = curStart, ce = curEnd, ns = next.getStart(), ne = newEnd;
                log.fine(() -> "Merging [" + cs + "," + ce + "] with " + next
                        + " → [" + cs + "," + ne + "]");
                curEnd = newEnd;
            } else {
                // Gap: finalize current and start a new one.
                merged.add(new Interval(curStart, curEnd));
                final int cs = curStart, ce = curEnd;
                log.fine(() -> "Gap before " + next + "; closing [" + cs + "," + ce + "]");
                curStart = next.getStart();
                curEnd = next.getEnd();
            }
        }
        merged.add(new Interval(curStart, curEnd)); // flush the final interval
        log.info(() -> "Merged locked periods = " + merged);
        return merged;
    }
}
